// Generated by herdr-i18n. The translated mods import "herdr" through this file,
// so the screens they open are the translated copies, not Herdr's own.
export * from "herdr";
import * as app from "herdr";

const { prefix, mods, screens } = __CONFIG__;
const own = (name) => (mods.includes(name) ? prefix + name : name);
const screen = (name, props) => app.openOverlay({ ...screens[name], mod: own(name), ...(props ? { props } : {}) });

export function openOverlay(spec) {
  return app.openOverlay(spec.mod ? { ...spec, mod: own(spec.mod) } : spec);
}

export function run(command, args = {}) {
  switch (command) {
    case "app.settings":
      if (!args.section) return app.run("mod.open", { name: own("settings") });
      // Asking for a section reopens Settings there, as Herdr's own command does.
      app.closeOverlay(`mod-${own("settings")}`);
      return screen("settings", { section: args.section });
    case "app.palette":
    case "app.help":
      return app.run("mod.open", { name: own(command.slice(4)) });
    case "app.welcome":
      return screen("welcome");
    case "app.feedback":
      return screen("feedback", { message: args.message ?? "", from: args.from ?? "person", layout: app.shared("layout") });
    case "app.whats_new": {
      const notes = app.updates().notes ?? [];
      return notes.length ? screen("whatsnew", { notes }) : run("app.settings", { section: "updates" });
    }
    case "mod.open":
      return app.run(command, { ...args, name: own(args.name) });
  }
  return app.run(command, args);
}
